# Gemini로 시트 이미지 생성 (원본은 tools/raw 에 저장)
$g = "$env:USERPROFILE\.claude\skills\gemini-image\generate.ps1"
$raw = Join-Path $PSScriptRoot 'raw'
New-Item -ItemType Directory -Force $raw | Out-Null
$mag = "on a completely flat solid pure magenta background (#FF00FF), no gradient, no floor, no shadow on the background"
$icon3d = "glossy 3D clay style game icons like premium mobile game UI (soft lighting, rounded shapes, vibrant saturated colors, subtle highlights), each object centered in its own cell of a strict evenly spaced grid with generous empty padding between cells, objects never touch each other, $mag, no text, no letters, no numbers"

function Gen($name, $prompt, $ar, $inputs) {
  $out = Join-Path $raw "$name.png"
  if (Test-Path $out) { Write-Host "skip $name"; return }
  if ($inputs) { & $g -Prompt $prompt -Out $out -AspectRatio $ar -InputImage $inputs }
  else { & $g -Prompt $prompt -Out $out -AspectRatio $ar }
}

Gen 'icons_ui' "A 4x4 grid sheet of 16 $icon3d. Row 1: crossed swords, golden trophy cup, royal golden crown, wooden treasure chest with gold. Row 2: golden key, steel padlock, rolled magic parchment scroll, shiny gold star. Row 3: glossy red heart, yellow lightning bolt, silver gear cog, arched wooden door glowing. Row 4: winged running sneaker, knight shield blue and gold, red megaphone, silver stopwatch." '1:1'
Gen 'icons_stats' "A 4x4 grid sheet of 16 $icon3d. Row 1: flexed muscular arm (strength), blue boot with small wings (agility), glowing pink brain (intelligence), green four-leaf clover (luck). Row 2: red heart shaped potion bottle (vitality), orange fire flame (courage), open blue spell book (wisdom), pink heart with sparkles (kindness). Row 3: rainbow colored feather (freedom), rolled treasure map, white thought bubble cloud, green up arrow with a star (level up). Row 4: red and white bullseye target with dart, cartoon hand pointing finger tapping, purple gift box with ribbon, small wooden school desk with chair." '1:1'
Gen 'icons_misc' "A 4x4 grid sheet of 16 $icon3d. Row 1: gold medal with ribbon, silver medal with ribbon, bronze medal with ribbon, smartphone. Row 2: two cute people silhouettes (group), venetian masquerade mask (secret), feather quill and ink pot, printer. Row 3: two red dice, round green play button, black and white checkered race flag, cute cartoon skull. Row 4: yellow banana peel, brown mud puddle, white and red athletics hurdle, glowing cyan double chevron arrows (speed boost pad)." '1:1'
Gen 'scenes_a' "A 3x3 grid of nine square storybook illustrations for a cute fantasy RPG adventure, consistent vibrant 2D painted game art style, each illustration fills its square, separated by thick pure white gutters, no text, no letters. 1: a school classroom door glowing with rainbow magic light. 2: an adventurer backpack with supplies on a forest path. 3: a funny green goblin guard blocking a forest path with a spear. 4: a giant ancient stone door with a glowing keyhole and runes. 5: a huge boulder blocking a mountain trail. 6: a small adventurer friend stuck in a green swamp reaching out. 7: a rushing blue river with stepping stones and a turtle. 8: a mysterious hooded merchant with a table of glowing potions. 9: a treasure vault door with a big number combination lock." '1:1'
Gen 'scenes_b' "A 3x3 grid of nine square storybook illustrations for a cute fantasy RPG adventure, consistent vibrant 2D painted game art style, each illustration fills its square, separated by thick pure white gutters, no text, no letters. 1: a shiny golden slime monster bouncing in a meadow. 2: a cozy campfire at night under stars in the forest. 3: a glowing golden level up burst of light with sparkles and stars. 4: a big red dragon sleeping on a pile of gold in a cave. 5: an ancient stone statue with glowing eyes in ruins. 6: an open treasure chest overflowing with gold coins. 7: a tiny fairy presenting three gift boxes. 8: a dark demon king castle on a cliff with purple lightning. 9: a school classroom door at sunset with warm light." '1:1'
$refs = @('warrior','mage','archer','thief','bard','cleric') | ForEach-Object { Join-Path $PSScriptRoot "..\public\assets\$_.jpg" }
Gen 'sprites_chars' "Using the six reference characters (knight warrior, wizard, elf archer, rogue thief, bard, cleric healer), draw all six of them as cute chibi game sprites in a dynamic RUNNING pose seen from the side, all facing right, full body including feet, same outfits and colors as the references, arranged in a strict 3 columns x 2 rows grid (row 1: warrior, wizard, archer; row 2: thief, bard, cleric), each centered in its cell with lots of empty padding, clean thick outlines, $mag, no text." '3:2' $refs
Gen 'fx_sheet' "A 4x4 grid sheet of 16 glowing magical game skill VFX sprites on a pure solid black background, each centered in its own cell with padding, bright neon glow, painterly anime game effects, no text. Row 1: blazing fireball with trail, blue arcane energy orb, glowing green arrow with motion trail, spinning silver dagger with blur. Row 2: burst of golden music notes, column of holy golden light, white crescent sword slash arc, big orange explosion burst. Row 3: blue lightning strike, cyan ice shard, purple star burst, green healing sparkles. Row 4: flaming meteor rock, expanding white shockwave ring, red impact hit spark, glowing blue experience crystal gem." '1:1'
Gen 'monsters' "A 2x2 grid sheet of four cute chibi monster game sprites seen from slightly above, each centered in its own cell with padding: a green jelly slime, a purple bat with spread wings, a red spotted mushroom monster, a small white ghost. Vibrant colors, clean thick outlines, $mag, no text." '1:1'
Gen 'arena_top' "Strictly top-down orthographic view (camera looking straight down, no perspective) of a large circular fantasy battle arena floor for a 2D top-down action game like Vampire Survivors: worn stone tiles, cracks, moss and grass patches around the edges, a faint glowing magic rune circle in the center, scattered small rocks and torches seen from above, rich colors, game background texture, no characters, no text." '16:9'
